window.TESTS = window.TESTS || [];
TESTS.push({
id: 3, name: "多益 3",
sets: [
{ part: 5, title: "Part 5 單句填空", qs: [
{n:1,q:"We're the first line of defense when it comes to _____ cybercrimes.",qz:"說到防範網路犯罪，我們是第一道防線。",o:["preventing","prevent","prevention","preventive"],oz:["防止（動名詞）","防止（原形）","預防（名詞）","預防性的"],a:0,ex:"when it comes to 的 to 是介系詞，後接動名詞 → preventing。常考陷阱！"},
{n:2,q:"You may not see it when you first meet him, but Bill has a(n) _____ temper.",qz:"你第一次見到比爾時可能看不出來，但他脾氣很火爆。",o:["fiery","windy","earthy","watery"],oz:["火爆的","多風的","樸實的","水汪汪的"],a:0,ex:"a fiery temper（暴躁的脾氣）為固定搭配。"},
{n:3,q:"One can only fail so many times before _____ by the higher-ups.",qz:"一個人失敗的次數有限，再多就會被高層訓斥了。",o:["reprimanding","reprimand","reprimanded","being reprimanded"],oz:["訓斥（主動）","訓斥（原形）","訓斥了","被訓斥"],a:3,ex:"before 是介系詞接動名詞；by the higher-ups 表示「被」訓斥 → 被動動名詞 being reprimanded。"},
{n:4,q:"I guess we'll just have to wait and see _____ the new project is approved or not.",qz:"我想我們只能等著看新專案會不會被核准了。",o:["unless","if","that","when"],oz:["除非","是否","（that 子句）","何時"],a:1,ex:"see 後接名詞子句，搭配 or not 表「是否」→ if（＝whether）。"},
{n:5,q:"Jeff is _____ charismatic and fun that he is always the life of the party.",qz:"傑夫非常有魅力又風趣，總是派對上的靈魂人物。",o:["very","much","such","so"],oz:["非常","很多","如此（接名詞）","如此（接形容詞）"],a:3,ex:"so + 形容詞 + that…（如此…以致於）。such 後要接名詞片語。"},
{n:6,q:"Can you tell me _____ you've been acting so strangely of late?",qz:"你能告訴我你最近為什麼表現得這麼奇怪嗎？",o:["why","who","what","when"],oz:["為什麼","誰","什麼","何時"],a:0,ex:"後面子句完整，問的是「原因」→ why。"},
{n:7,q:"Jason is looking for a new job because he feels he is overworked and _____ here.",qz:"傑森在找新工作，因為他覺得自己在這裡工作過量又薪水過低。",o:["underpaid","underpays","underpay","underpaying"],oz:["薪水過低的","少付（第三人稱）","少付（原形）","少付中"],a:0,ex:"與 overworked（過勞的）對等，都是過去分詞當形容詞 → underpaid。"},
{n:8,q:"Once I get some time _____ from work, I'll finally be able to run a few errands and clean my house.",qz:"等我工作有空休假時，終於可以去辦點雜事、打掃房子了。",o:["in","by","off","with"],oz:["在…裡","藉由","休假、不上班","與"],a:2,ex:"time off（休假）為固定用法；get time off from work。"},
{n:9,q:"It is important to stay on top of current events if you want to have _____ conversations about contemporary international politics.",qz:"如果你想對當代國際政治有見地地交談，掌握時事很重要。",o:["informant","inform","informed","information"],oz:["線人","通知（動詞）","有見識的、消息靈通的","資訊（名詞）"],a:2,ex:"修飾名詞 conversations 需形容詞 → informed conversations（有見地的對話）。"},
{n:10,q:"Courtney believes that the payment didn't go through _____ a processing error.",qz:"考特妮認為付款沒成功是因為處理上的錯誤。",o:["due to","in terms of","with regard to","apart from"],oz:["由於","就…而言","關於","除了"],a:0,ex:"表原因、後接名詞 → due to。"},
{n:11,q:"Rita feels it is necessary to space _____ one's meals in order to keep one's blood sugar regular.",qz:"莉塔認為必須把三餐間隔開來，才能讓血糖維持穩定。",o:["by","out","with","between"],oz:["藉由","分散開","與","在…之間"],a:1,ex:"space out（把…間隔開、分散開）為片語動詞。"},
{n:12,q:"I don't like to _____, so I devote all my thought and energy to tackling one major project at a time.",qz:"我不喜歡一心多用，所以一次只把心力投注在一個大專案上。",o:["think","direct","complete","multitask"],oz:["思考","指揮","完成","同時處理多項工作"],a:3,ex:"後句「一次只做一個專案」→ 不喜歡 multitask（多工）。"},
{n:13,q:"Don't you think that finishing this workload within such a short time frame is too heavy a _____ for most employees to bear?",qz:"你不覺得要在這麼短時間內完成這些工作量，對大多數員工來說負擔太重了嗎？",o:["burden","resource","preference","performance"],oz:["負擔","資源","偏好","表現"],a:0,ex:"heavy、bear（承受）→ burden（負擔）。注意 too + 形容詞 + a + 名詞 的語序。"},
{n:14,q:"Sure, that house looks nice on the outside, but what's the _____ like?",qz:"沒錯，那房子外面看起來不錯，但裡面是什麼樣子？",o:["interior","exterior","anterior","posterior"],oz:["內部","外部","前面的","後面的"],a:0,ex:"與 on the outside（外觀）對比 → interior（內部）。"},
{n:15,q:"The government's new trade _____ have had a crippling effect on international business.",qz:"政府新的貿易限制已對國際商業造成重創。",o:["restricted","restricting","restrictions","restricts"],oz:["受限的","限制中","限制（名詞複數）","限制（動詞）"],a:2,ex:"所有格 government's + trade + 名詞；動詞 have 是複數 → restrictions。"},
{n:16,q:"I have no idea _____ we are going to finish this project on time and under budget.",qz:"我完全不知道我們要怎麼準時又不超支地完成這個專案。",o:["how","who","what","when"],oz:["如何","誰","什麼","何時"],a:0,ex:"後面子句完整，問「方法」→ how。"},
{n:17,q:"My goodness! What a horrible accident. It's a miracle _____ is completely uninjured!",qz:"天啊！好可怕的車禍。大家都毫髮無傷真是奇蹟！",o:["no one","myself","everything","everyone"],oz:["沒有人","我自己","每件事","每個人"],a:3,ex:"是奇蹟 → 大家都沒受傷 → everyone。no one is uninjured 意思變成「每個人都受傷」。"},
{n:18,q:"Although the pay raise would have been nice, I had to _____ on the promotion because relocating to a new branch would have been difficult for my children.",qz:"雖然加薪很好，但我不得不放棄升遷，因為調到新分店對我的孩子來說會很辛苦。",o:["pass","deny","reject","surrender"],oz:["放棄（pass on）","否認","拒絕","投降"],a:0,ex:"pass on something（婉拒、放棄某機會）。reject/deny 不接 on。"},
{n:19,q:"Drake _____ this obnoxious air of superiority ever since he got a perfect score on his employee evaluation.",qz:"自從德瑞克在員工考核拿到滿分後，他就一直帶著一副討人厭的優越感。",o:["had been","has had","had","has been"],oz:["曾經是","一直有（現在完成）","有（過去）","一直是"],a:1,ex:"ever since + 過去時間 → 主句用現在完成式；「擁有」某種態度用 have → has had。"},
{n:20,q:"It is uncertain whether Kevin will stay _____ with the company after the incident.",qz:"發生那件事後，凱文是否會繼續留在公司還不確定。",o:["in","on","near","under"],oz:["在…裡","繼續留任","在附近","在下面"],a:1,ex:"stay on（繼續留任）為片語動詞。"},
{n:21,q:"Will you _____ my petition for additional employee benefits?",qz:"你會支持我爭取更多員工福利的請願嗎？",o:["rear","back","behind","hindmost"],oz:["養育","支持","在後面","最後面的"],a:1,ex:"back 當動詞＝支持（support）。"},
{n:22,q:"It looks like we'll be bunking at your brother's house _____ the damage to our apartment is repaired.",qz:"看來我們得暫住你哥哥家，直到公寓的損壞修好為止。",o:["until","whereas","meanwhile","formerly"],oz:["直到","然而","同時","以前"],a:0,ex:"暫住到修好為止 → until，可連接子句。"},
{n:23,q:"Our regular lecturer, Mr. Gray, was sick, so we had someone _____ for him today.",qz:"我們平常的講師格雷先生生病了，所以今天找了別人代課。",o:["substitution","has substituted","substituted","substitute"],oz:["代替（名詞）","已代替","被代替","代替（原形）"],a:3,ex:"使役動詞 have + 人 + 原形動詞（主動）→ had someone substitute。"},
{n:24,q:"How many times do we have to go _____ this? Don't visit questionable Web sites when using a company computer.",qz:"這件事我們到底要講幾次？用公司電腦時不要逛可疑的網站。",o:["up","on","over","above"],oz:["上","繼續","重複講、複習","在上方"],a:2,ex:"go over（反覆說明、檢討）。"},
{n:25,q:"This data shows how our sales _____ have remained steady across all four quarters.",qz:"這些數據顯示我們的銷售數字在四個季度都維持穩定。",o:["figures","expanses","measures","assemblages"],oz:["數字","廣闊區域","措施","集合"],a:0,ex:"sales figures（銷售數字）為固定搭配。"},
{n:26,q:"I'm afraid that your current sales pitch just isn't good enough. You'll have to _____ it before our prospective clients arrive next week.",qz:"恐怕你目前的推銷說詞不夠好。在潛在客戶下週來之前，你必須修改。",o:["revise","renew","repeat","reread"],oz:["修改","更新、續約","重複","重讀"],a:0,ex:"不夠好 → 要修改 → revise。"},
{n:27,q:"You can get addicted to pretty much anything. I for _____ can't stop checking my e-mails.",qz:"人幾乎什麼都可能上癮。就拿我來說，我就停不了一直收信。",o:["me","one","you","us"],oz:["我","（for one 就…來說）","你","我們"],a:1,ex:"I for one（至少我就是；就我而言）是固定用法。"},
{n:28,q:"How much time would you say you spend _____ social media each day?",qz:"你覺得自己每天花多少時間在社群媒體上？",o:["to","in","on","about"],oz:["到","在…裡","在…上","關於"],a:2,ex:"spend time on something（花時間在某事上）。"},
{n:29,q:"Don't worry. You only have a cold. It'll run _____ course over a few weeks, and you'll be fine.",qz:"別擔心，你只是感冒。過幾週自然會好，你就沒事了。",o:["it's","it","its","itself"],oz:["它是","它","它的","它自己"],a:2,ex:"run its course（自然發展、自然結束）；名詞 course 前用所有格 its。it's ＝ it is。"},
{n:30,q:"The government's financial stimulus package was implemented in an attempt to _____ the effects of the economic crisis.",qz:"政府推出財政振興方案，試圖扭轉經濟危機的影響。",o:["spiral","release","reverse","advance"],oz:["盤旋上升","釋放","扭轉","推進"],a:2,ex:"振興方案是為了「扭轉」危機的影響 → reverse。"}
]},
{ part: 6, title: "Part 6｜Tesla 特斯拉",
passage: `<p>Surprisingly, Tesla has __(31)__ to turn a profit as of 2016. The company encountered criticism with its car's auto-pilot feature and operating system. Chinese researchers demonstrated that the car could be hacked when they opened the car's doors without a key and controlled its brakes __(32)__ .</p><p>Despite these setbacks, Tesla has seen a(n) __(33)__ in deliveries during its third sales quarter of 2016, shipping over 24,500 cars. __(34)__</p>`,
pz: `<p>令人意外的是，截至 2016 年特斯拉仍尚未獲利。這家公司的汽車自動駕駛功能與作業系統受到批評。中國研究人員證明了這款車可以被駭入：他們不用鑰匙就打開車門，還遠端控制了剎車。</p><p>儘管有這些挫折，特斯拉 2016 年第三季的交車量大增，出貨超過 24,500 輛。這比前一年同一季的交車量多出一倍以上。</p>`,
qs: [
{n:31,q:"Question 31",o:["already","then","yet","far"],oz:["已經","然後","尚未","遠"],a:2,ex:"have yet to + V ＝ 尚未…。Surprisingly 也暗示「還沒獲利」。"},
{n:32,q:"Question 32",o:["remote","remotely","remoteness","remotes"],oz:["遙遠的","遠端地","偏遠（名詞）","遙控器"],a:1,ex:"修飾動詞 controlled 用副詞 → remotely（遠端地）。"},
{n:33,q:"Question 33",o:["echo","spike","decay","reflection"],oz:["回音","激增","衰退","反射"],a:1,ex:"Despite these setbacks（儘管挫折）表轉折，出貨超過兩萬多輛 → 交車量「激增」spike。"},
{n:34,q:"Question 34",o:["This is more than double the amount delivered in the same quarter the year prior.","The company blames this decline on bad press it has received over the years.","This number is expected to rise dramatically in 2015, when new laws take effect.","These numbers have led some analysts to believe that this year could be their last."],oz:["這比前一年同季的交車量多一倍以上。","公司把這次下滑歸咎於多年來的負面報導。","這數字預計在 2015 年新法生效時大幅上升。","這些數字讓分析師認為今年可能是他們最後一年。"],a:0,ex:"前句說交車量大增，接著補充「比去年同期多一倍」最合理。(B)(D) 是負面，與 spike 矛盾；(C) 2015 已過去。"}
]},
{ part: 6, title: "Part 6｜Jessica Butcher 冒牌者症候群",
passage: `<p>Jessica Butcher is the co-founder of Blippar, an augmented reality app. She spoke with BBC about what it is like being a successful female entrepreneur in the world of tech business. __(35)__ Butcher, numerous female entrepreneurs suffer from what she calls "imposter syndrome," which essentially means that some women feel __(36)__ , resulting in them holding back their ideas and second-guessing themselves more than their male peers.</p><p>Butcher asserts that women are also more likely to be perfectionists, and though this is __(37)__ , it can prevent things from getting done. Butcher admits that she used to be both insecure and a perfectionist, but has since changed upon discovering that her male peers are frequently as clueless as she is when facing the rapid changes of the tech market, and that a lot of their success comes from confidence. __(38)__</p>`,
pz: `<p>Jessica Butcher 是擴增實境 App「Blippar」的共同創辦人。她接受 BBC 訪問，談到在科技業界身為成功女性創業家是什麼感覺。根據 Butcher 的說法，許多女性創業家受「冒牌者症候群」所苦，基本上就是有些女性覺得自己資格不夠，導致她們比男性同儕更常把想法藏起來、質疑自己。</p><p>Butcher 主張女性也比較容易是完美主義者，雖然這很有幫助，卻可能讓事情無法完成。Butcher 承認她過去既缺乏安全感又是完美主義者，但後來發現男性同儕面對科技市場的快速變化時常常和她一樣毫無頭緒，而他們的成功很大一部分來自自信，從此她就改變了。她現在實踐目前的經商方式：多交流、把自己的想法說出去，然後持續進步。</p>`,
qs: [
{n:35,q:"Question 35",o:["As well as","According to","Based on","Owing to"],oz:["以及","根據（某人說法）","基於","由於"],a:1,ex:"引述某人的說法 → According to Butcher。"},
{n:36,q:"Question 36",o:["overqualified","disqualification","disqualify","underqualified"],oz:["資格過高的","失格（名詞）","取消資格（動詞）","資格不足的"],a:3,ex:"feel + 形容詞；冒牌者症候群是覺得自己「不夠格」→ underqualified。"},
{n:37,q:"Question 37",o:["helpful","assisting","convenient","cooperative"],oz:["有幫助的","協助中","方便的","合作的"],a:0,ex:"though this is ___, it can prevent… → 讓步：雖然完美主義「有幫助」，卻也會阻礙進度 → helpful。"},
{n:38,q:"Question 38",o:["She now practices her current approach to business: talking, getting one's ideas out there, and making progress.","With this knowledge in hand, Butcher is focused on making people more aware of this little-known disease.","Butcher is now refining her skills in the hopes of someday landing the job of her dreams.","Butcher believes that women—not men—will be the driving forces in agriculture now."],oz:["她現在實踐目前的經商方式：多交流、說出想法、持續進步。","有了這個認識，她專注於讓大家認識這種罕見疾病。","她正在精進技能，希望有天找到夢想工作。","她認為現在女性（而非男性）將是農業的推動力。"],a:0,ex:"前句說她已經改變（不再缺乏自信），接著說明她現在的做法最合理。冒牌者症候群不是疾病；她已是創辦人；與農業無關。"}
]},
{ part: 6, title: "Part 6｜Panel Interviewing 小組面試",
passage: `<p>To: All Managers<br>From: Human Resources<br>Subject: RE: Panel Interviewing</p><p>Starting next month, we will begin using a new technique in interviewing. In order to hire a new employee, you and two other managers from related departments will meet and conduct a panel interview. __(39)__</p><p>As with all job interviews, panel interviews serve two purposes: First, they allow the interviewers to determine if candidates are suitable for the position. Second, they give candidates an opportunity to learn about the business and the job. __(40)__ the structure of a panel interview may be more intimidating to a candidate than a one-on-one interview, this can be a useful way of determining how candidates fare under pressure. However, the session should not turn into __(41)__ or hostile grilling. There are a number of tips and tricks to conducting a panel interview that help ensure it proceeds according to plan and assists in __(42)__ the best person for the role.</p>`,
pz: `<p>收件者：全體經理<br>寄件者：人力資源部<br>主旨：回覆：小組面試</p><p>從下個月開始，我們將採用新的面試方式。招募新員工時，您將與另外兩位相關部門的經理一起進行小組面試。以下說明這種方式將如何讓公司受益。</p><p>和所有求職面試一樣，小組面試有兩個目的：第一，讓面試官判斷應徵者是否適合這個職位；第二，讓應徵者有機會了解公司和工作內容。由於小組面試的形式可能比一對一面試更令應徵者感到壓力，這可以是觀察應徵者在壓力下表現如何的好方法。不過，面試不應演變成咄咄逼人或充滿敵意的盤問。進行小組面試有許多技巧，可以幫助確保面試按計畫進行，並協助找出最適合這個職位的人選。</p>`,
qs: [
{n:39,q:"Question 39",o:["One-on-one interviews have proven to be the most effective style.","It's best for the prospective employee to feel at ease during the interview.","We'll go over the several intended purposes of this format.","The following outlines why this style will benefit our company."],oz:["一對一面試已被證明是最有效的方式。","應徵者面試時最好感到自在。","我們會檢討這種形式的幾個預定目的。","以下說明這種方式將如何讓公司受益。"],a:3,ex:"引出下文對小組面試好處的說明 → (D)。(A) 與推行小組面試矛盾。"},
{n:40,q:"Question 40",o:["Since","Until","Whenever","Only if"],oz:["由於","直到","每當","只有當"],a:0,ex:"「因為」小組面試讓人有壓力，所以能看出應徵者抗壓能力 → Since（＝because）。"},
{n:41,q:"Question 41",o:["aggressive","passive","lenient","complacent"],oz:["咄咄逼人的","被動的","寬容的","自滿的"],a:0,ex:"與 hostile grilling（敵意盤問）並列，語意相近 → aggressive。"},
{n:42,q:"Question 42",o:["identified","identification","identifies","identifying"],oz:["被找出的","識別（名詞）","找出（第三人稱）","找出（動名詞）"],a:3,ex:"介系詞 in 後接動名詞，且後面有受詞 the best person → identifying。"}
]},
{ part: 6, title: "Part 6｜Server Policies 伺服器政策",
passage: `<p>To: All employees<br>From: Brian Woods, IT Director<br>Subject: Server policies</p><p>Our new servers are now online. Company policy __(43)__ employees to keep most company materials stored on the servers and not on their desktops, so please make use of the servers.</p><p>Currently, we have separate servers for different departments, and folders on those servers for different work groups. __(44)__</p><p>The servers are __(45)__ daily at 7:00 p.m. If you lose a document or have problems on your desktop, we can usually restore the previous day's version within half an hour. Please contact us if you require any __(46)__ .</p>`,
pz: `<p>收件者：全體員工<br>寄件者：資訊部主任 Brian Woods<br>主旨：伺服器政策</p><p>我們的新伺服器已經上線。公司政策要求員工將大部分公司資料存放在伺服器上，而不是存在個人電腦桌面，所以請善用伺服器。</p><p>目前我們為不同部門設有不同的伺服器，伺服器上也為不同工作小組設有資料夾。請務必避免將文件存到不屬於您部門的伺服器上。</p><p>伺服器每天晚上 7 點會備份。如果您遺失文件或電腦出問題，我們通常可以在半小時內還原前一天的版本。如需任何協助，請與我們聯繫。</p>`,
qs: [
{n:43,q:"Question 43",o:["requires","guarantees","compensates","causes"],oz:["要求","保證","補償","導致"],a:0,ex:"require + 人 + to V（要求某人做…）→ Company policy requires employees to…"},
{n:44,q:"Question 44",o:["As a result of this new policy, a document can only be edited by one employee at a time.","Because of this, we'll need to assign new computers to each department.","Make sure to avoid saving documents on servers not designated for your department.","As our server space is limited, all departments will need to share the same servers for the time being."],oz:["由於新政策，一份文件一次只能由一人編輯。","因此我們需要為每個部門配發新電腦。","請務必避免將文件存到不屬於您部門的伺服器上。","因伺服器空間有限，各部門暫時要共用同一台伺服器。"],a:2,ex:"前句說各部門有各自的伺服器，接著提醒「不要存到別部門的伺服器」最合理。(D) 與「分開的伺服器」矛盾。"},
{n:45,q:"Question 45",o:["back up","having backed up","backing up","backed up"],oz:["備份（原形）","已備份","備份中","被備份"],a:3,ex:"伺服器是「被」備份 → are + p.p. 被動 → backed up。"},
{n:46,q:"Question 46",o:["assist","assistance","assistant","assisted"],oz:["協助（動詞）","協助（名詞）","助理","被協助的"],a:1,ex:"any 後接名詞；require any assistance（需要任何協助）。assistant 是人，且可數單數前不用 any。"}
]},
{ part: 7, title: "Part 7｜募資會議的訊息",
passage: `<p><b>JED BRIGHTON (2:24 p.m.)</b><br>Hey, I just got out of the meeting with Fujiwara Capital.</p><p><b>SUSAN DENT (2:28 p.m.)</b><br>How did it go? Don't tell me they're not going to fund us . . .</p><p><b>JED BRIGHTON (2:31 p.m.)</b><br>No, they're willing to fund us. They offered $1.7 million, which is more than what we were asking for.</p><p><b>SUSAN DENT (2:33 p.m.)</b><br>That's great! Wait, did they want equity? Remember, Bob said he didn't want to give away part of his company.</p><p><b>JED BRIGHTON (2:35 p.m.)</b><br>They want 20 percent equity. I tried to work with them, but they seemed pretty firm on that number.</p><p><b>SUSAN DENT (2:36 p.m.)</b><br>Hmm, the boss is not going to be happy about that. Try to line up some more investor meetings.</p>`,
pz: `<p><b>Jed Brighton（下午 2:24）</b><br>嘿，我剛和 Fujiwara Capital 開完會。</p><p><b>Susan Dent（2:28）</b><br>結果如何？別跟我說他們不打算投資我們……</p><p><b>Jed Brighton（2:31）</b><br>不，他們願意投資。他們出價 170 萬美元，比我們要求的還多。</p><p><b>Susan Dent（2:33）</b><br>太好了！等等，他們要股權嗎？記得 Bob 說過他不想讓出公司的一部分。</p><p><b>Jed Brighton（2:35）</b><br>他們要 20% 的股權。我試著跟他們協調，但他們對這個數字似乎很堅持。</p><p><b>Susan Dent（2:36）</b><br>嗯，老闆不會高興的。試著多安排幾場投資人會議吧。</p>`,
qs: [
{n:47,q:"What is suggested about Bob?",qz:"關於 Bob，文中暗示了什麼？",o:["He is a potential investor.","He is the boss.","He is going to be very happy.","He made a low offer."],oz:["他是潛在投資人。","他是老闆。","他會很高興。","他出價很低。"],a:1,ex:"Bob 不想讓出「他的公司」的股份，接著 Susan 說 the boss is not going to be happy → Bob 就是老闆。"},
{n:48,q:"At 2:28 p.m., what does Susan mean when she writes \"Don't tell me\"?",qz:"2:28 時，Susan 寫「Don't tell me」是什麼意思？",o:["Be quiet about . . .","I hope it's not true that . . .","I suspect that . . .","I expect that . . ."],oz:["別說出…","我希望…不是真的","我懷疑…","我預期…"],a:1,ex:"Don't tell me… 是口語「該不會…吧」，表示擔心並希望那不是真的。"}
]},
{ part: 7, title: "Part 7｜體能健康問卷",
passage: `<p><b>In general, how would you rate your health?</b><br>Excellent / Very good / Good / <b>Fair ✔</b> / Poor</p><p><b>How often do you perform the following?</b></p><table><tr><th></th><th>Often</th><th>Sometimes</th><th>Seldom or Never</th></tr><tr><td>Eating Junk Food</td><td>V</td><td></td><td></td></tr><tr><td>Indulging in sedentary hobbies</td><td>V</td><td></td><td></td></tr><tr><td>Exercise</td><td></td><td></td><td>V</td></tr></table><p><b>The following items are activities you might do on a typical day. Do you have difficulty performing these activities, and if so, how much difficulty?</b></p><table><tr><th></th><th>Yes, a lot of difficulty</th><th>Yes, a little difficulty</th><th>No difficulty</th></tr><tr><td><b>Strenuous activities</b>, such as running, lifting heavy objects, or playing sports</td><td>V</td><td></td><td></td></tr><tr><td><b>Moderate activities</b>, such as moving a table or cleaning your house</td><td></td><td>V</td><td></td></tr><tr><td>Lifting or carrying groceries</td><td></td><td>V</td><td></td></tr><tr><td>Climbing many flights of stairs</td><td></td><td>V</td><td></td></tr><tr><td>Bending or kneeling</td><td></td><td></td><td>V</td></tr><tr><td>Walking more than a kilometer</td><td></td><td>V</td><td></td></tr></table><p><b>If accepted for the position, would you be capable of performing any of the following?</b></p><table><tr><th></th><th>Yes</th><th>No</th></tr><tr><td>Lifting up to 100 kg</td><td></td><td>V</td></tr><tr><td>Chopping down a door</td><td></td><td>V</td></tr><tr><td>Sprinting up many flights of stairs while carrying heavy equipment</td><td></td><td>V</td></tr><tr><td>Withstanding extreme heat</td><td>V</td><td></td></tr></table>`,
pz: `<p><b>整體而言，你如何評價自己的健康？</b>極佳／很好／好／<b>普通 ✔</b>／差</p><p><b>你多常做以下事情？</b><br>吃垃圾食物：經常<br>沉迷於久坐不動的嗜好：經常<br>運動：很少或從不</p><p><b>以下是日常可能做的活動。你做這些活動有困難嗎？困難程度如何？</b><br>劇烈活動（如跑步、搬重物、運動）：很困難<br>中度活動（如搬桌子、打掃房子）：有點困難<br>提或搬運雜貨：有點困難<br>爬好幾層樓梯：有點困難<br>彎腰或跪下：沒有困難<br>走超過一公里：有點困難</p><p><b>若錄取此職位，你能否做到以下事項？</b><br>舉起 100 公斤：否<br>劈開一扇門：否<br>攜帶重裝備衝上好幾層樓梯：否<br>承受極高溫：是</p>`,
qs: [
{n:49,q:"Given the content of the survey, what job is the writer most likely applying for?",qz:"根據問卷內容，填寫者最可能在應徵什麼工作？",o:["Nurse","Soldier","Firefighter","Police officer"],oz:["護理師","軍人","消防員","警察"],a:2,ex:"劈開門、背重裝備衝上樓梯、承受極高溫 → 都是消防員的工作內容。"},
{n:50,q:"What can be most likely assumed about the person who has filled this survey out?",qz:"關於填寫這份問卷的人，最可能的推論是什麼？",o:["He or she is dishonest.","He or she is extremely strong.","He or she can run great distances.","He or she is not suited for the job."],oz:["他／她不誠實。","他／她非常強壯。","他／她能跑很遠。","他／她不適合這份工作。"],a:3,ex:"健康普通、很少運動、劇烈活動很困難、多數工作要求都做不到 → 不適合這份工作。"}
]},
{ part: 7, title: "Part 7｜被丟掉的裝置藝術",
passage: `<p>In lighter news, a local city worker, Trenton Miller, caused a humorous incident which nearly cost him his job. Mr. Miller, who works as a garbage collector, was driving his truck along its daily route when he saw something which he believed to be a large pile of litter. As it turns out, what he threw into his garbage truck and dumped in the city's landfill was a piece of installation art valued at US$80,000. The artist, Emile Torrance, was hired by the city to make an environmental statement. According to Mr. Torrance, he wanted to make art that commented on how much garbage people throw away and how litter is ruining beautiful cityscapes. Thus, he simulated a pile of trash in a nearby park. Once Mr. Miller's supervisor told him that he'd thrown away some expensive art, he drove back to the dump in search of it. He didn't find the simulated garbage, and so, in a panic, he threw some actual garbage back in the park. When asked for a comment on the incident, Mr. Torrance laughingly remarked that he thought Mr. Miller's substitution was an improvement. No charges have been filed.</p>`,
pz: `<p>來點輕鬆的新聞：當地一名市府員工 Trenton Miller 引發了一起差點害他丟掉工作的趣事。擔任垃圾清潔員的 Miller 先生開著垃圾車沿每日路線行駛時，看到他以為是一大堆垃圾的東西。結果，他丟進垃圾車並倒進市立垃圾掩埋場的，竟是一件價值 8 萬美元的裝置藝術。藝術家 Emile Torrance 受市府委託創作具環保意涵的作品。根據 Torrance 先生的說法，他想創作能反映人們丟棄多少垃圾、以及垃圾如何破壞美麗市容的藝術。因此他在附近公園模擬了一堆垃圾。Miller 先生的主管告訴他丟掉了昂貴藝術品後，他開車回垃圾場尋找，但沒找到那堆模擬垃圾，於是他慌張之下把一些真正的垃圾丟回公園。被問到對此事的看法時，Torrance 先生笑著說，他認為 Miller 先生的替代品是一種改進。目前沒有人提出告訴。</p>`,
qs: [
{n:51,q:"Why did Trenton throw a piece of expensive art in the city dump?",qz:"Trenton 為什麼把昂貴的藝術品丟進垃圾場？",o:["He hates modern art.","It looked like garbage.","Mr. Torrance ordered him to.","He didn't know it had fallen into his truck."],oz:["他討厭現代藝術。","它看起來像垃圾。","Torrance 先生叫他這麼做。","他不知道它掉進了他的卡車。"],a:1,ex:"作品本來就是「模擬一堆垃圾」，他以為是 a large pile of litter → 看起來像垃圾。"},
{n:52,q:"Which adjective best describes Emile's state of mind once he learned that his artwork had been thrown out?",qz:"Emile 得知作品被丟掉後的心情最適合用哪個形容詞描述？",o:["Angry","Jealous","Amused","Saddened"],oz:["生氣的","嫉妒的","覺得好笑的","難過的"],a:2,ex:"「Mr. Torrance laughingly remarked…」他笑著說替代品更好 → amused（覺得有趣）。"}
]},
{ part: 7, title: "Part 7｜印度廢鈔",
passage: `<p>On November 8, 2016, Narendra Modi, India's prime minister, made a televised announcement that older versions of the country's 500- and 1,000-rupee notes would no longer be honored as currency, effective immediately. Modi assured Indian citizens that they would not have to rush to the banks to change over their currency, as banks would allow citizens to exchange their old high-value notes for the newer 500- and 2,000-rupee versions until the end of 2016. Still, many Indians lined up for hours in a hurried attempt to rid themselves of their suddenly useless lucre. The reason for the government's abrupt dismissal of the nation's old high-value notes was to combat black-market counterfeiting, tax evasion, and administrative corruption, as it will now be difficult for politicians to take cash bribes with only small currency temporarily available. However, as of January 9, 2017, many economists have reported that the plan has not only failed to curb these behaviors, but also caused a counterfeit currency crisis because of the government's halving the amount of money in circulation.</p>`,
pz: `<p>2016 年 11 月 8 日，印度總理莫迪在電視上宣布，舊版 500 和 1,000 盧比紙鈔即刻起不再作為貨幣使用。莫迪向印度人民保證不必急著去銀行換鈔，因為銀行在 2016 年底前都會讓民眾把舊的大面額紙鈔換成新版 500 和 2,000 盧比紙鈔。儘管如此，許多印度人仍排隊好幾個小時，急著處理掉這些突然變得毫無用處的錢。政府突然廢除舊大鈔的理由，是為了打擊黑市偽鈔、逃稅和行政貪腐，因為在暫時只有小額鈔票流通的情況下，政治人物將很難收受現金賄賂。然而，截至 2017 年 1 月 9 日，許多經濟學家指出，這項計畫不但沒能遏止這些行為，還因為政府讓流通貨幣減半，造成了偽鈔危機。</p>`,
qs: [
{n:53,q:"When could Indian citizens no longer spend their old 500- and 1,000-rupee notes on goods and services?",qz:"印度人民從什麼時候起不能再用舊的 500 和 1,000 盧比紙鈔消費？",o:["January 1, 2017","January 9, 2017","November 8, 2016","December 31, 2016"],oz:["2017 年 1 月 1 日","2017 年 1 月 9 日","2016 年 11 月 8 日","2016 年 12 月 31 日"],a:2,ex:"「would no longer be honored as currency, effective immediately」→ 宣布當天 11/8 立即生效。12/31 是換鈔期限，不是消費期限。"},
{n:54,q:"Which of the following is NOT one of the Indian government's stated reasons for the abrupt currency swap?",qz:"下列何者「不是」印度政府宣稱突然換鈔的理由？",o:["Preventing bribery","Preventing tax evasion","Preventing counterfeiting","Preventing the rise of the middle class"],oz:["防止賄賂","防止逃稅","防止偽鈔","防止中產階級崛起"],a:3,ex:"理由是 counterfeiting、tax evasion、corruption（cash bribes）；沒提到中產階級。"}
]},
{ part: 7, title: "Part 7｜Samsung Note7 投訴信",
passage: `<p>Dear Samsung Customer Service,</p><p>I purchased the Samsung Galaxy Note7 on August 20, 2016, and excitedly took it home. Several days after using the product, I awoke to find my bedroom filled with smoke! Fortunately, I was able to unplug the device and safely move it into a steel garbage can before extinguishing the fire. Little damage was done to my home, but I was still quite shaken. I was pleased to hear that you issued a product recall on September 2 after additional phones were reported exploding. I partook in the recall and returned my crispy Note7 in exchange for a new one. However, news stories of the replacement Note7s combusting have me too scared to even unbox my replacement. I'm aware that you wanted to make your product as sleek and stylish as possible without compromising the phone's battery power, but I've read story after story about how the phone's powerful battery and cramped design are the reasons behind Note7s immolating while charging. I would be satisfied with receiving an older version of Samsung phone coupled with a reimbursement for my Note7 as compensation for my inconvenience.</p><p>Thank you,</p><p>Janos Burlie</p>`,
pz: `<p>親愛的三星客服：</p><p>我在 2016 年 8 月 20 日購買了三星 Galaxy Note7，興奮地帶回家。使用幾天後，我醒來發現臥室裡滿是煙霧！幸好我及時拔掉插頭，把手機安全地移到鐵製垃圾桶裡再撲滅火勢。家裡損害不大，但我仍心有餘悸。聽說你們在 9 月 2 日因更多手機傳出爆炸而發布產品召回，我很高興。我參加了召回，把燒焦的 Note7 換成新機。然而，替換的 Note7 也起火的新聞讓我害怕到連新機都不敢拆封。我知道你們想讓產品盡可能輕薄時尚又不犧牲電池效能，但我讀過一篇又一篇報導，說手機的強大電池和擁擠的設計就是 Note7 充電時起火燃燒的原因。作為對我造成不便的補償，我希望能收到一支舊款三星手機，外加 Note7 的退款，這樣我就滿意了。</p><p>謝謝，<br>Janos Burlie</p>`,
qs: [
{n:55,q:"What prompted Samsung's product recall?",qz:"是什麼促使三星進行產品召回？",o:["An information leak about the Note7","The Note7's operating system being hacked","A superior product to the Note7 being released","The possibility of the Note7 bursting into flames"],oz:["Note7 資訊外洩","Note7 作業系統被駭","推出比 Note7 更好的產品","Note7 可能起火燃燒"],a:3,ex:"「issued a product recall… after additional phones were reported exploding」→ 爆炸起火的風險。"},
{n:56,q:"What component of the Samsung Galaxy Note7 does Janos assert is periodically defective?",qz:"Janos 認為 Galaxy Note7 的哪個零件常出問題？",o:["The screen","The battery","The speakers","The hard drive"],oz:["螢幕","電池","喇叭","硬碟"],a:1,ex:"「the phone's powerful battery and cramped design are the reasons behind Note7s immolating」→ 電池。"},
{n:57,q:"What does Janos request as compensation?",qz:"Janos 要求什麼補償？",o:["A fixed Note7 with a guarantee of safety","An older Samsung cell phone and a refund","A public apology and a large cash settlement","A smartphone from a competitor with his old data on it"],oz:["修好的 Note7 加安全保證","舊款三星手機加退款","公開道歉與大筆和解金","存有舊資料的競爭品牌手機"],a:1,ex:"「receiving an older version of Samsung phone coupled with a reimbursement」→ 舊款手機＋退款。"}
]},
{ part: 7, title: "Part 7｜出貨延遲的訊息",
passage: `<p><b>Bart Smith [4:41 p.m.]</b> Hey, guys. Big problem. The shipment has been delayed, and our client has already specified they won't accept any more late deliveries.</p><p><b>Andy Smart [4:41 p.m.]</b> What's the deal? Have you contacted Bower?</p><p><b>Bart Smith [4:42 p.m.]</b> Yes, I e-mailed them this morning. Apparently there was a transportation issue, but that's all they gave me.</p><p><b>Erin Garfield [4:42 p.m.]</b> Would have liked a bit more info. Well, is the whole shipment delayed, or is any of it still on track? I know they usually ship their equipment separately.</p><p><b>Bart Smith [4:43 p.m.]</b> Yes, I asked them about that. The shin guards, shoulder pads, and elbow pads were all shipped together. Those are all good to go.</p><p><b>Erin Garfield [4:43 p.m.]</b> But?</p><p><b>Bart Smith [4:43 p.m.]</b> But the helmets, gloves, sticks, and skates are all delayed.</p><p><b>Andy Smart [4:44 p.m.]</b> OK. Crisis management mode, everyone. I'll contact the client immediately and let them know forces beyond our control have delayed half the shipment. Here's to hoping they understand.</p>`,
pz: `<p><b>Bart Smith［下午 4:41］</b> 嘿，各位，大事不妙。貨延誤了，而客戶已經明說不會再接受任何延遲交貨。</p><p><b>Andy Smart［4:41］</b> 怎麼回事？你聯絡 Bower 了嗎？</p><p><b>Bart Smith［4:42］</b> 聯絡了，我今天早上寄了信。顯然是運輸出了問題，但他們只告訴我這些。</p><p><b>Erin Garfield［4:42］</b> 真希望能多知道一點。那麼，是整批貨都延誤，還是有部分仍照常出貨？我知道他們的裝備通常分開出貨。</p><p><b>Bart Smith［4:43］</b> 對，我問過了。護脛、護肩和護肘是一起出貨的，那些都沒問題。</p><p><b>Erin Garfield［4:43］</b> 但是？</p><p><b>Bart Smith［4:43］</b> 但是頭盔、手套、球棍和冰刀鞋都延誤了。</p><p><b>Andy Smart［4:44］</b> 好，大家進入危機處理模式。我會馬上聯絡客戶，讓他們知道因不可抗力因素，有一半的貨延誤了。希望他們能諒解。</p>`,
qs: [
{n:58,q:"Who or what is Bower?",qz:"Bower 是誰或是什麼？",o:["The speakers' client","A shipping company","The speakers' colleague","A sporting goods manufacturer"],oz:["對話者的客戶","貨運公司","對話者的同事","運動用品製造商"],a:3,ex:"Bower 出貨護具、頭盔、球棍、冰刀鞋等裝備（they usually ship their equipment）→ 運動用品製造商。運輸問題是 Bower 回報的，它本身不是貨運公司。"},
{n:59,q:"What can we infer from the conversation?",qz:"從對話可以推論出什麼？",o:["The client has provided transportation.","The client has lost patience with late shipments.","The client will not receive any of their equipment on time.","This is the client's first time doing business with the speakers."],oz:["客戶有提供運輸。","客戶對延遲出貨已失去耐心。","客戶的裝備全都無法準時收到。","這是客戶第一次和他們做生意。"],a:1,ex:"客戶「won't accept any more late deliveries」（不再接受延遲）→ 以前延遲過，已失去耐心。護具類仍準時，(C) 錯。"},
{n:60,q:"What does Bart mean when he writes \"but that's all they gave me\"?",qz:"Bart 寫「但他們只告訴我這些」是什麼意思？",o:["He was given a free product.","All the equipment was transported.","He is fully informed about all the details.","No further information was provided about the issue."],oz:["他拿到免費產品。","所有裝備都已運送。","他完全掌握所有細節。","對方沒有提供更多問題的資訊。"],a:3,ex:"對方只說是運輸問題，沒給其他細節 → 沒有更多資訊。Erin 接著也說 Would have liked a bit more info。"}
]},
{ part: 7, title: "Part 7｜新加坡豪宅",
passage: `<p>Recently, Singapore's luxury real estate has become comparatively cheap when juxtaposed with properties of similar size and quality on the international market. —[1]— It does mean that multinational buyers could potentially score prime real estate at an excellent price and perhaps opt to buy low now and sell high later. A property analyst in Singapore, Brandon Lee from JPMorgan, documented the 15 to 25 percent drop in luxury residential prices since the market's price peak in 2011. —[2]— According to Lee, properties in other business capitals, such as London, Hong Kong, and New York, are 165 percent more expensive than those found in Singapore. In 2016, the second largest group of Singapore luxury real estate buyers was made up of Americans, which is unusual because the market is typically dominated by Indonesian, Malaysian, and Chinese buyers. —[3]— Lee believes that this may be due to tax treaties exempting buyers of certain nationalities, such as Americans and the Swiss, from having to pay an additional 15 percent on the property. —[4]—</p>`,
pz: `<p>最近，新加坡的豪宅和國際市場上類似大小與品質的房產相比，變得相對便宜。—[1]— 這並不代表任何人都買得起，因為以中產階級買家的標準來看仍然非常昂貴。但這確實意味著跨國買家有機會以極佳的價格買到頂級房產，或許可以選擇現在低價買進、日後高價賣出。摩根大通駐新加坡的房地產分析師 Brandon Lee 記錄到，自 2011 年市場價格高峰以來，豪宅價格下跌了 15% 到 25%。—[2]— 根據 Lee 的說法，倫敦、香港、紐約等其他商業之都的房產比新加坡貴 165%。2016 年，新加坡豪宅的第二大買家群是美國人，這很不尋常，因為這個市場通常由印尼、馬來西亞和中國買家主導。—[3]— Lee 認為這可能是因為租稅協定讓某些國籍的買家（如美國人和瑞士人）免付額外 15% 的房產稅。—[4]—</p>`,
qs: [
{n:61,q:"According to the article, what is true about Singapore's luxury properties?",qz:"根據文章，關於新加坡豪宅下列何者正確？",o:["They will definitely continue to lose value.","They were at their most expensive in 2011.","They are among the most expensive in the world.","They are being purchased exclusively by Americans."],oz:["一定會繼續貶值。","2011 年時最貴。","是世界上最貴的之一。","只有美國人在買。"],a:1,ex:"「since the market's price peak in 2011」→ 2011 年是價格高峰。"},
{n:62,q:"According to the article, why might more Americans be buying Singaporean luxury real estate?",qz:"根據文章，為什麼可能有更多美國人買新加坡豪宅？",o:["They are exempt from paying certain taxes.","New York luxury real estate prices are now too low.","Most American businesses are based in Singapore.","They wish to own more real estate than Chinese buyers."],oz:["他們免付某些稅。","紐約豪宅現在太便宜。","大多數美國企業設在新加坡。","他們想比中國買家擁有更多房產。"],a:0,ex:"租稅協定讓美國人免付額外 15% → 免某些稅。"},
{n:63,q:"According to the article, what might be one reason a multinational buyer may purchase luxury property in Singapore?",qz:"根據文章，跨國買家購買新加坡豪宅的可能原因之一是什麼？",o:["The property is so cheap that anyone can afford it.","Property prices will definitely increase by the end of the year.","A buyer could potentially sell the property at a profit in the future.","A buyer could gain access to American tax advantages by owning a property."],oz:["房子便宜到人人買得起。","房價年底一定會漲。","買家未來可能轉賣獲利。","擁有房產就能享美國稅務優惠。"],a:2,ex:"「buy low now and sell high later」→ 未來轉賣獲利。注意 definitely 的選項通常太絕對。"},
{n:64,q:"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"This does not mean that anyone can purchase them, as they are still very expensive by the standards of a middle-class buyer.\"",qz:"下列句子最適合放在哪個位置？\n「這並不代表任何人都買得起，因為以中產階級的標準來看仍非常昂貴。」",o:["[1]","[2]","[3]","[4]"],oz:["[1]","[2]","[3]","[4]"],a:0,ex:"[1] 前說豪宅變便宜，接「這不代表人人買得起」，後面再接 It does mean…（但確實意味著…），形成 does not mean / does mean 的對照。"}
]},
{ part: 7, title: "Part 7｜退休理財",
passage: `<p>Though many middle-class workers are entitled to pensions through their employers, these pensions do not guarantee that the retiree can live as comfortably as when they were working. Therefore, many middle-class men and women are choosing to continue working into their senior years because these older workers don't wish to completely discontinue their steady flow of income. Sooner or later, however, elderly employees will have to come to terms with their gradually diminishing ability to clock in long hours. Thus, saving for retirement, be it a working one or otherwise, is still a wise decision. Making a series of safe, low-interest investments throughout middle age can better ensure that you have a nest egg. High-risk investments are fine when you are younger, but wean off them as you enter middle age; you don't want your future livelihood to be at risk should the market prove unstable. Additionally, property you own, such as your home or apartment, is another form of investment—one which you can cash in on when you wish to fully or partially retire. So make sure you maintain your property to reap your full reward.</p>`,
pz: `<p>雖然許多中產階級勞工有權透過雇主領取退休金，但這些退休金並不能保證退休者能過得和工作時一樣舒適。因此，許多中產階級男女選擇工作到老年，因為這些年長勞工不想完全中斷穩定的收入來源。然而，年長員工遲早得接受自己長時間工作的能力逐漸下降。因此，為退休存錢——無論是邊工作邊退休或完全退休——仍是明智的決定。在整個中年時期進行一系列安全、低利率的投資，更能確保你有一筆養老金。年輕時做高風險投資沒關係，但進入中年後要逐漸減少；萬一市場不穩，你可不希望未來的生計受到威脅。此外，你擁有的房產，例如房子或公寓，是另一種投資——當你想完全或部分退休時可以變現。所以務必維護好你的房產，才能獲得最大回報。</p>`,
qs: [
{n:65,q:"Which of the following is NOT an asset the passage describes as a potential source of income once you are retired?",qz:"下列何者「不是」文章提到的退休後潛在收入來源？",o:["Property","Pensions","Investments","State assistance"],oz:["房產","退休金","投資","政府補助"],a:3,ex:"文中提到 pensions、investments、property，沒有提到政府補助。"},
{n:66,q:"According to the passage, why do middle-class, senior-aged workers most often choose to keep working?",qz:"根據文章，中產階級的年長勞工為什麼最常選擇繼續工作？",o:["To support their children","They don't have a choice.","To maintain their current standard of living","To save enough to start their own businesses"],oz:["為了養孩子","他們別無選擇。","為了維持目前的生活水準","為了存錢創業"],a:2,ex:"退休金無法保證過得一樣舒適，他們不想中斷穩定收入 → 維持生活水準。"},
{n:67,q:"When should one stop making high-risk investments?",qz:"什麼時候應該停止高風險投資？",o:["In one's early 40s","In the middle of one's career","In one's senior years","Early in one's career"],oz:["40 歲出頭","職涯中期","老年時","職涯早期"],a:0,ex:"「wean off them as you enter middle age」→ 進入中年時（約 40 歲出頭）。"}
]},
{ part: 7, title: "Part 7｜加美軟木材爭端",
passage: `<p>Despite their free trade agreement, Canada and the United States don't always trade seamlessly. One of the largest and longest lasting trade disputes between the two nations has been over Canadian soft lumber. Currently, Canada has the world's largest forest product trade balance—almost US$14.6 billion in 2013. Its largest importer of lumber is the United States. The quarrel between the two nations comes from America's assertion that the Canadian government subsidizes its lumber industry (a claim which Canada refutes), allowing it to set lumber prices at a consistently low rate and giving it an unfair advantage over American lumber companies. This has prompted America to repeatedly implement countervailing duties—import taxes meant to balance out the inherently low price of Canadian soft lumber imports. As a result, an on-again, off-again legal battle has been occurring since the early 1980s, with new rulings and agreements being reached, only to be challenged and renegotiated several years later. In 2006, the two nations signed the Softwood Lumber Agreement, which states that the United States must lift its countervailing duties if Canada agrees to keep its lumber prices above a set limit. The contract expired nine years later, and, as of 2016, has yet to be renegotiated. This gives Canadian lumber companies unrestricted access to the American soft lumber market.</p>`,
pz: `<p>儘管加拿大與美國簽有自由貿易協定，兩國的貿易並非總是順暢無阻。兩國之間規模最大、持續最久的貿易爭端之一，就是加拿大軟木材問題。目前加拿大擁有全球最大的林產品貿易順差——2013 年將近 146 億美元。它最大的木材進口國是美國。兩國爭執的起因是美國主張加拿大政府補貼其木材產業（加拿大否認此說法），使其能長期把木材價格壓低，對美國木材公司形成不公平的優勢。這促使美國一再實施平衡稅——一種用來抵銷加拿大軟木材進口低價的進口稅。結果，自 1980 年代初以來，雙方的法律戰時斷時續，新的裁決與協議達成後，幾年後又遭到挑戰並重新談判。2006 年，兩國簽署《軟木材協定》，規定只要加拿大同意把木材價格維持在一定限度以上，美國就必須取消平衡稅。該協定在九年後到期，而截至 2016 年仍未重新談判。這讓加拿大木材公司能不受限制地進入美國軟木材市場。</p>`,
qs: [
{n:68,q:"According to the article, what is true about Canada?",qz:"根據文章，關於加拿大何者正確？",o:["It purchases most of its lumber from America.","Its lumber prices are definitely set entirely by the market.","Its lumber can be sold more cheaply than American lumber.","It wishes to implement countervailing trade duties on its lumber exports."],oz:["它的木材大多向美國購買。","它的木材價格一定完全由市場決定。","它的木材能比美國木材賣得便宜。","它想對自己的木材出口課平衡稅。"],a:2,ex:"加拿大木材價格 consistently low，美國才要課稅平衡 → 加拿大木材比較便宜。"},
{n:69,q:"What is at the core of America's lumber dispute with Canada?",qz:"美國與加拿大木材爭端的核心是什麼？",o:["Canadian lumber is of an inferior quality to American lumber.","Canada refuses to admit its socialist traits to its capitalist trade ally.","Importing Canadian lumber is hurting America's lumber businesses.","Canada is buying American lumber at a cheaper price than America pays for Canadian lumber."],oz:["加拿大木材品質較差。","加拿大拒絕向資本主義盟友承認其社會主義特質。","進口加拿大木材傷害了美國木材業。","加拿大用比美國付的更低價買美國木材。"],a:2,ex:"美國認為加拿大補貼造成低價，對美國木材公司形成不公平優勢 → 傷害美國木材業。"},
{n:70,q:"What happened in 2015?",qz:"2015 年發生了什麼事？",o:["Canada entered NAFTA.","The soft lumber agreement ended.","Canada won the soft lumber dispute.","America employed countervailing duties on Canadian lumber."],oz:["加拿大加入北美自由貿易協定。","軟木材協定到期了。","加拿大贏得軟木材爭端。","美國對加拿大木材課平衡稅。"],a:1,ex:"2006 年簽約，「expired nine years later」→ 2006 + 9 = 2015 年到期。"},
{n:71,q:"Which of the following thematic statements is most closely expressed by this article?",qz:"下列哪一個主旨最接近這篇文章所表達的？",o:["Even allied nations and close trading partners can have long disputes.","America is always an unfair international trading partner, even to its allies.","Canada's socialist tendencies grant it an unfair economic edge internationally.","Though two countries appear to be international allies, they are secretly enemies."],oz:["即使是盟國和密切的貿易夥伴也可能有長期爭端。","美國總是不公平的貿易夥伴，連對盟友也是。","加拿大的社會主義傾向給了它不公平的國際經濟優勢。","兩國表面上是盟友，其實暗中是敵人。"],a:0,ex:"開頭「儘管有自由貿易協定，兩國貿易並非總是順暢」，接著講持續數十年的爭端 → (A)。其他選項太偏激。"}
]},
{ part: 7, title: "Part 7｜Liberty Air 道歉信",
passage: `<p style="text-align:center"><b>Liberty Air</b><br>450 Main Street<br>New York, NY 10024<br>1-800-565-6000</p><p>Dear Liberty Air customers,</p><p>—[1]— I'd like to take this time to say to all our valued customers that we at Liberty Air are deeply sorry and embarrassed for our performance over the Christmas season.</p><p>Last week was the worst operational week in Liberty Air's eleven-year history. —[2]—</p><p>The fact is we let you down. Nothing is more important than regaining your trust. —[3]— All of us here hope you will give us the opportunity to once again welcome you on board and provide you with the positive Liberty Air experience you have come to expect. —[4]—</p><p>Sincerely,<br><i>David Cannon</i><br>Chief Executive Officer</p>`,
pz: `<p style="text-align:center"><b>Liberty 航空</b><br>紐約大街 450 號</p><p>親愛的 Liberty 航空旅客：</p><p>—[1]— 我想藉此機會向所有尊貴的旅客表達，我們 Liberty 航空對於聖誕假期期間的表現深感抱歉與慚愧。</p><p>上週是 Liberty 航空十一年歷史中營運最糟的一週。—[2]— 西南部遭受嚴重冬季風暴後，許多旅客受困、延誤或航班被取消。</p><p>事實是我們讓您失望了。沒有什麼比重新贏回您的信任更重要。—[3]— 我們全體都希望您能給我們機會，再次歡迎您登機，並為您提供您所期待的美好 Liberty 航空體驗。—[4]—</p><p>執行長 David Cannon 敬上</p>`,
qs: [
{n:72,q:"What is the main purpose of David Cannon's letter?",qz:"David Cannon 這封信的主要目的是什麼？",o:["To inform customers about a flight delay","To let customers know about a future flight cancellation","To offer savings on future travels with Liberty Air","To apologize for disappointing Liberty Air's customers"],oz:["通知旅客航班延誤","告知旅客未來航班取消","提供未來搭乘的優惠","為讓旅客失望致歉"],a:3,ex:"「deeply sorry and embarrassed」「we let you down」→ 道歉信。"},
{n:73,q:"How long has Liberty Air been in operation?",qz:"Liberty 航空營運多久了？",o:["One season","One year","Over a decade","Twenty years"],oz:["一季","一年","超過十年","二十年"],a:2,ex:"「Liberty Air's eleven-year history」→ 11 年，超過十年。"},
{n:74,q:"What is NOT mentioned in the letter?",qz:"信中「沒有」提到什麼？",o:["Expectations of customers flying with Liberty Air again","An apology to customers for a week of poor service","A money-back guarantee from Liberty Air","The promise for better service in the future"],oz:["期待旅客再次搭乘","為一週的糟糕服務道歉","退款保證","承諾未來提供更好服務"],a:2,ex:"信中有道歉、希望再次服務、提供正面體驗，但沒提到退款。"},
{n:75,q:"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Many of you were either stranded, delayed or had flights canceled following the severe winter storm in the Southwest.\"",qz:"下列句子最適合放在哪個位置？\n「西南部遭受嚴重冬季風暴後，許多旅客受困、延誤或航班被取消。」",o:["[1]","[2]","[3]","[4]"],oz:["[1]","[2]","[3]","[4]"],a:1,ex:"[2] 前一句說「上週是營運最糟的一週」，接著說明具體發生了什麼事最自然。"}
]},
{ part: 7, title: "Part 7｜三房公寓出租",
passage: `<p style="text-align:center"><b>Notice: Luxurious 3-Bedroom Apartment Available for Rent from March 3.</b></p><p>My name is Olivia Reynard. I am looking for a tenant or tenants to take over my apartment, which I am leaving on March 2. Here are some details regarding the apartment:</p><p>3 bedrooms<br>2 bathrooms<br>A spacious balcony<br>A kitchen, complete with gas stove and oven<br>Semi-furnished; contains a television, couches, a bed, a dining room table and chairs<br>Pet-friendly<br>Internet fees are covered by the landlord.<br>A damage deposit of two months' rent is required.<br>Tenants must sign a six-month contract.<br>Rent is NT$20,000 per month plus utilities.<br>The apartment is located on the fifth floor, and there is no elevator.</p><p>If you have any additional questions, feel free to text me at 5555-043-446 or e-mail me at <u>reynard55@yahoo.com</u>.</p><hr><p>Dear Olivia,</p><p>I am interested in your apartment, but I have a few questions. Firstly, is the balcony open-air or enclosed? Secondly, does either bathroom contain a bathtub? Thirdly, how close is the apartment to an MRT stop? Finally, although it seems your landlord is fine with pets, are the neighbors also OK with me keeping cats? I ask because even though they're indoor kitties, they can sometimes be a little noisy, and I don't want to annoy anyone. Also, I'd be available to move in a week after your listed move-in date.</p><p>Best wishes,</p><p>Steven Lawburn</p>`,
pz: `<p style="text-align:center"><b>公告：豪華三房公寓 3 月 3 日起出租</b></p><p>我叫 Olivia Reynard。我要在 3 月 2 日搬走，正在找房客接手我的公寓。以下是公寓的一些資訊：</p><p>3 間臥室<br>2 間浴室<br>寬敞的陽台<br>廚房，附瓦斯爐和烤箱<br>半附家具：有電視、沙發、床、餐桌椅<br>可養寵物<br>網路費由房東支付<br>需付兩個月租金的押金<br>房客須簽六個月合約<br>租金每月新台幣 20,000 元，水電另計<br>公寓位於五樓，沒有電梯</p><p>如有其他問題，歡迎傳簡訊到 5555-043-446 或寄信到 reynard55@yahoo.com。</p><hr><p>親愛的 Olivia：</p><p>我對你的公寓有興趣，但有幾個問題。第一，陽台是露天的還是封閉的？第二，兩間浴室有浴缸嗎？第三，公寓離捷運站多近？最後，雖然你的房東似乎不介意寵物，但鄰居也能接受我養貓嗎？我會問是因為雖然牠們是室內貓，有時還是會有點吵，我不想打擾任何人。另外，我可以在你列出的入住日一週後搬進去。</p><p>祝好，<br>Steven Lawburn</p>`,
qs: [
{n:76,q:"What important detail did Olivia leave out of her ad?",qz:"Olivia 的廣告漏掉了什麼重要資訊？",o:["The monthly rent","The damage deposit","Her contact information","The apartment's location"],oz:["月租金","押金","她的聯絡方式","公寓的地點"],a:3,ex:"租金、押金、聯絡方式都有寫，但沒寫地址在哪裡；Steven 也問「離捷運站多近」。"},
{n:77,q:"Which of the following shares the closest meaning with \"pet-friendly\" in this context?",qz:"下列何者與本文中的「pet-friendly」意思最接近？",o:["The landlord likes pets.","All of the neighbors love pets.","Pets are allowed in this apartment.","This apartment is completely pet-proof."],oz:["房東喜歡寵物。","所有鄰居都愛寵物。","這間公寓允許養寵物。","這間公寓完全防寵物破壞。"],a:2,ex:"租屋廣告的 pet-friendly ＝ 可以養寵物。"},
{n:78,q:"Which response might satisfactorily answer Steven's fourth question?",qz:"哪個回答最能滿意地回應 Steven 的第四個問題？",o:["\"I don't know my neighbors.\"","\"No one in the building is allergic.\"","\"The apartment is completely soundproof.\"","\"The furniture is completely indestructible.\""],oz:["「我不認識鄰居。」","「大樓裡沒人過敏。」","「公寓完全隔音。」","「家具完全不會壞。」"],a:2,ex:"他擔心貓太吵會打擾鄰居 → 「完全隔音」最能解除他的顧慮。"},
{n:79,q:"If the electric bill equates to NT$1,000 per month, the water bill works out to NT$400 per month, and the Internet bill is NT$600 per month, how much would the tenant have to pay each month?",qz:"如果電費每月 1,000 元、水費 400 元、網路費 600 元，房客每月要付多少錢？",o:["NT$20,000","NT$21,000","NT$21,400","NT$22,000"],oz:["20,000 元","21,000 元","21,400 元","22,000 元"],a:2,ex:"租金 20,000 + 電費 1,000 + 水費 400 ＝ 21,400。網路費由房東支付，不用算！"},
{n:80,q:"When is Steven available to move in to the apartment?",qz:"Steven 什麼時候可以搬進公寓？",o:["March 2","March 3","March 5","March 10"],oz:["3 月 2 日","3 月 3 日","3 月 5 日","3 月 10 日"],a:3,ex:"入住日是 3 月 3 日，他說「a week after」→ 3 + 7 ＝ 3 月 10 日。"}
]},
{ part: 7, title: "Part 7｜University of Devon 問卷",
passage: `<p>Dear Mrs. Gainsborough,</p><p>The University of Devon is surveying graduates and contributors in order to better understand their attitudes and perceptions. This study has been designed to assist in improving our fund-raising programs and our scheduled lectures and workshops, as well as how we promote these events.</p><p>Short Forest Ltd., an independent market research firm, has been selected to officially execute this inquiry aimed at helping to understand your opinions. Fear not—the company is utilizing methods to collect and display survey data which ensure that answers are not linked to respondents.</p><p>The project's goal is to generate more successful communication with graduates and contributors. Your efforts will assist the university in accomplishing this.</p><p>Please participate in this survey by following this link: www.surveysallthetime.com/shortforest</p><p>The survey should only require 15-20 minutes to complete. The deadline for completion is March 31.</p><p>Thank you in advance for your contribution to this process.</p><p>Gaston Clerik<br>Director of the Alumni Association<br>University of Devon</p><hr><p>Dear Miranda,</p><p>Recently, many alumni have received an invitation to contribute to the University of Devon's Communication Evaluation Survey. Due to insufficient data, the survey's deadline has been extended. If you have not had a chance to complete the survey, the university would appreciate your involvement now.</p><p>The University of Devon Alumni Association serves more than 300,000 graduates and contributors. Because of such, the institution wishes to better ascertain which programs and events former students would like to be organized by the Alumni Association. Your input will be of great importance as it will assist in the selection of which future benefits we intend to offer to former students and donors. All survey answers will be reported to committee members in aggregate only.</p><p>Completing the survey now enters you into an optional draw for two free tickets to the city's annual Food and Folk Music Festival.</p><p>Some survey takers reported an inability to complete the survey. If you have technical problems or questions about the survey, please contact Mildred Pierce of Short Forest Ltd. at millyp5598@shortforest.com or 5555-662-4343.</p><p>The survey closes on April 30.</p><p>All the best,</p><p>Gaston Clerik<br>Director of the Alumni Association<br>University of Devon</p>`,
pz: `<p>親愛的 Gainsborough 女士：</p><p>Devon 大學正在對畢業生與捐助者進行調查，以更了解他們的態度與看法。這項研究旨在協助改善我們的募款計畫、預定的講座與工作坊，以及這些活動的宣傳方式。</p><p>獨立市場研究公司 Short Forest 有限公司已獲選正式執行這項旨在了解您意見的調查。請放心——該公司使用的資料蒐集與呈現方法能確保答案不會與填答者連結。</p><p>本計畫的目標是與畢業生和捐助者建立更成功的溝通。您的參與將協助大學達成此目標。</p><p>請點擊此連結參與調查：www.surveysallthetime.com/shortforest</p><p>問卷只需 15–20 分鐘即可完成。截止日期為 3 月 31 日。</p><p>預先感謝您對此過程的貢獻。</p><p>Devon 大學校友會會長 Gaston Clerik</p><hr><p>親愛的 Miranda：</p><p>最近許多校友都收到了參與 Devon 大學溝通評估調查的邀請。由於資料不足，調查截止日期已延長。如果您還沒機會填寫問卷，大學非常感謝您現在參與。</p><p>Devon 大學校友會服務超過 30 萬名畢業生與捐助者。因此，學校希望更確切了解校友希望校友會舉辦哪些計畫與活動。您的意見非常重要，因為它將協助我們選擇未來要提供給校友與捐助者的福利。所有問卷答案只會以彙總方式向委員會成員報告。</p><p>現在完成問卷，即可參加抽獎（可自由選擇），有機會獲得兩張本市年度美食與民謠音樂節的免費門票。</p><p>有些填答者反映無法完成問卷。若您遇到技術問題或對問卷有疑問，請聯絡 Short Forest 公司的 Mildred Pierce：millyp5598@shortforest.com 或 5555-662-4343。</p><p>問卷將於 4 月 30 日截止。</p><p>Devon 大學校友會會長 Gaston Clerik 敬上</p>`,
qs: [
{n:81,q:"What is the purpose of this survey?",qz:"這份問卷的目的是什麼？",o:["To learn how to improve the university's courses","To learn about the public's perception of the university","To learn about the careers currently held by former alumni","To learn how to improve its notifications, events, and fund-raisers"],oz:["了解如何改善大學課程","了解大眾對大學的看法","了解校友目前的職業","了解如何改善通知、活動與募款"],a:3,ex:"「improving our fund-raising programs and our scheduled lectures and workshops, as well as how we promote these events」→ 募款、活動與宣傳（通知）。"},
{n:82,q:"Why was the second e-mail sent?",qz:"為什麼寄出第二封郵件？",o:["Because there was an error in the first e-mail","Because Gaston wants to raffle off his tickets","Because the survey did not obtain sufficient data","Because Miranda did not respond to the previous e-mail"],oz:["因為第一封郵件有錯","因為 Gaston 想抽獎送出他的票","因為問卷沒有蒐集到足夠資料","因為 Miranda 沒回覆前一封郵件"],a:2,ex:"「Due to insufficient data, the survey's deadline has been extended」→ 資料不足。"},
{n:83,q:"About how long was the deadline for the survey extended?",qz:"問卷截止日期大約延長了多久？",o:["One year","One month","Twenty days","Fifteen days"],oz:["一年","一個月","二十天","十五天"],a:1,ex:"原本 3 月 31 日截止，延到 4 月 30 日 → 約一個月。"},
{n:84,q:"What can be most safely assumed about the survey?",qz:"關於這份問卷，最安全的推論是什麼？",o:["It only exists online.","It was designed by Mildred Pierce.","It will take at least 40 minutes to complete.","It contains both written and multiple choice elements."],oz:["它只有線上版。","它是 Mildred Pierce 設計的。","至少要花 40 分鐘才能完成。","它包含申論和選擇題。"],a:0,ex:"參與方式只有點連結（線上），問題也是技術問題 → 只有線上版。只需 15–20 分鐘；題型沒提到。"},
{n:85,q:"After it is collected, how will the data from the survey most likely be presented?",qz:"問卷資料蒐集後，最可能以什麼方式呈現？",o:["It will be presented altogether.","It will never be presented.","Through video testimonies","In pamphlets containing personal quotations"],oz:["以整體彙總方式呈現。","永遠不會公開。","透過影片證言","以含個人引述的手冊"],a:0,ex:"「reported to committee members in aggregate only」→ in aggregate ＝ 彙總、整體呈現。"}
]},
{ part: 7, title: "Part 7｜Telewiz 有線電視帳單",
passage: `<p style="text-align:center"><b><i>Telewiz™ cable television</i></b></p><p>Join the millions of people who have access to the best in entertainment, including sports, movies, and your favorite shows! Act now and if you order before July 31, your Internet will be free!+ Check out our monthly packages below.</p><table><tr><th>Bronze</th><th>Silver</th><th>Gold</th><th>Platinum</th></tr><tr><td>$14.99*</td><td>$24.99*</td><td>$44.99*</td><td>$59.99*+</td></tr><tr><td>45 basic channels<br>11 sports channels<br>3 movie channels</td><td>70 basic channels<br>11 sports channels<br>6 movie channels</td><td>95 basic channels<br>11 sports channels<br>10 movie channels</td><td>All 152 basic channels<br>All 23 sports channels<br>All 20 movie channels</td></tr></table><p>* Beginning September 1, credit card payments will incur a $5 fee.<br>+ Free Internet offer extends <u>only</u> to the Platinum $59.99 package.</p><hr><p style="text-align:center"><b><i>Telewiz™ bill for services</i></b></p><table><tr><th>DATE</th><th>DESCRIPTION</th><th>AMOUNT</th></tr><tr><td colspan="3"><b>PREVIOUS BILLING PERIOD (July 15-August 14)</b></td></tr><tr><td>Aug 14<br>Aug 15</td><td>Previous balance<br>Payment received (Visa XXX89)<br>Balance</td><td>$44.99<br>-$44.99<br>$0.00</td></tr><tr><td colspan="3"><b>NEW BILLING PERIOD (August 15-September 14)</b><br><i>Your bill will automatically be charged to Visa XXX89 on September 14.</i></td></tr><tr><td>Aug 15</td><td>Platinum cable package<br>Internet<br>Fee</td><td>$59.99<br>$29.99<br>$5</td></tr><tr><td></td><td><b>AMOUNT DUE:</b></td><td><b>$94.98</b></td></tr></table><hr><p>Dear Telewiz customer service,</p><p>I have a problem. I saw your ad about the new promotion you were running. On August 15, I called your company and upgraded from your Gold package to your Platinum package so I could get more sports channels and free Internet. However, when I got the bill, I noticed that I was charged for both the Platinum package and Internet. The offer said that Internet should be free. In addition, I was also charged a $5.00 fee, but I'm not sure what it's for. My bill should be $59.99. Can you please fix it?</p><p>Sincerely,<br>Mary Lewandowski</p>`,
pz: `<p style="text-align:center"><b>Telewiz™ 有線電視</b></p><p>加入數百萬享受最佳娛樂的觀眾行列，包括體育、電影以及你最愛的節目！立即行動，7 月 31 日前訂購，網路免費！+ 請看以下每月方案。</p><p>銅級 $14.99*：45 個基本頻道、11 個體育台、3 個電影台<br>銀級 $24.99*：70 個基本頻道、11 個體育台、6 個電影台<br>金級 $44.99*：95 個基本頻道、11 個體育台、10 個電影台<br>白金級 $59.99*+：全部 152 個基本頻道、全部 23 個體育台、全部 20 個電影台</p><p>* 自 9 月 1 日起，信用卡付款將加收 $5 手續費。<br>+ 免費網路優惠<u>僅限</u>白金級 $59.99 方案。</p><hr><p style="text-align:center"><b>Telewiz™ 服務帳單</b></p><p><b>上期帳單（7/15–8/14）</b><br>8/14 前期餘額 $44.99；8/15 已收款（Visa XXX89）-$44.99；餘額 $0.00</p><p><b>本期帳單（8/15–9/14）</b><br><i>您的帳單將於 9 月 14 日自動從 Visa XXX89 扣款。</i><br>8/15 白金級有線電視方案 $59.99；網路 $29.99；手續費 $5<br><b>應付金額：$94.98</b></p><hr><p>親愛的 Telewiz 客服：</p><p>我遇到一個問題。我看到你們正在進行的新促銷廣告。8 月 15 日我打電話到你們公司，從金級方案升級為白金級方案，好看更多體育台並享有免費網路。然而，我收到帳單時發現白金方案和網路都被收費了。廣告說網路應該免費。此外，我還被收了 $5.00 的費用，但我不知道那是什麼。我的帳單應該是 $59.99。可以請你們修正嗎？</p><p>Mary Lewandowski 敬上</p>`,
qs: [
{n:86,q:"In the advertisement, the phrase \"Act now\" is closest in meaning to",qz:"廣告中「Act now」的意思最接近",o:["quickly take advantage","call for more information","take your time","read closely"],oz:["趕快把握機會","打電話詢問更多資訊","慢慢來","仔細閱讀"],a:0,ex:"Act now（立即行動）後接限時優惠 → 趕快把握。"},
{n:87,q:"How can customers save money when ordering services?",qz:"顧客訂購服務時要怎麼省錢？",o:["Pay by check","Pay by credit card","Order the Platinum package","Order the Gold package"],oz:["用支票付款","用信用卡付款","訂白金級方案","訂金級方案"],a:2,ex:"免費網路只限白金方案 → 訂白金方案可省網路費。信用卡反而要加收 $5。"},
{n:88,q:"What is probably true about Mary's services from the previous month?",qz:"關於 Mary 上個月的服務，何者可能為真？",o:["She was paying for the Silver package.","She was paying for the Platinum package.","She was not paying for cable TV service.","She did not have Internet service."],oz:["她付的是銀級方案。","她付的是白金級方案。","她沒付有線電視費。","她沒有網路服務。"],a:3,ex:"上期餘額只有 $44.99 ＝ 金級方案費用，沒有網路費 → 上個月沒有網路服務。"},
{n:89,q:"Why was Mary charged an extra $5?",qz:"Mary 為什麼被多收 $5？",o:["Because she paid with a credit card","Because she canceled her service","Because she made a late payment","Because she ordered a movie"],oz:["因為她用信用卡付款","因為她取消了服務","因為她遲繳","因為她點了電影"],a:0,ex:"帳單自動從 Visa（信用卡）扣款，而 9 月 1 日起信用卡付款加收 $5 手續費。"},
{n:90,q:"What problem does Mary mention in her letter?",qz:"Mary 在信中提到什麼問題？",o:["She is not getting all of her sports channels.","She believes she was overcharged.","Her service was canceled.","Her television reception has been really bad."],oz:["她沒收到全部體育台。","她認為被多收費了。","她的服務被取消了。","她的電視收訊很差。"],a:1,ex:"她說網路應免費、$5 不知道是什麼，帳單應只有 $59.99 → 認為被多收。（但她其實是 8/15 才訂，晚於 7/31 優惠期限。）"}
]},
{ part: 7, title: "Part 7｜Mallard 開發案與老太太",
passage: `<p>Dear Ms. Macfield:</p><p>My name is Arron Brawn, and I am writing on behalf of the developers who wish to purchase your property. Just like we made clear to you before, we intend to demolish all of the old properties we purchase to erect a shopping center and a series of condominiums in order to rejuvenate your neighborhood—Mallard, Seattle. As your property has been valued at—and this is a liberal estimate—US$150,000, our previous offer of US$750,000 should have been accepted. Your house is the last impediment to our project, and, as you can see from the attached timeline, your refusal to sell is turning into a major hindrance. We were supposed to begin construction on Condo A seven days ago. Thus, we are prepared to make you the more than generous offer of US$1,000,000 for your property. This sum would enable you to not only purchase a nicer property, but also live comfortably in your old age.</p><p>Thank you for your time,</p><p>Arron Brawn</p><table><tr><th colspan="3">Condo A Project Timeline</th></tr><tr><th>Task</th><th>Start</th><th>End</th></tr><tr><td>Start date</td><td>9/21/2017</td><td>–</td></tr><tr><td>Demo prep</td><td>10/1/2017</td><td>10/6/2017</td></tr><tr><td>Demolition</td><td>10/6/2017</td><td>10/24/2017</td></tr><tr><td>Excavation</td><td>10/25/2017</td><td>10/29/2017</td></tr><tr><td>Concrete</td><td>11/1/2017</td><td>11/13/2017</td></tr><tr><td>Backfill</td><td>11/13/2017</td><td>11/15/2017</td></tr><tr><td>Framing</td><td>10/25/2017</td><td>12/5/2017</td></tr><tr><td>Roof</td><td>11/19/2017</td><td>12/10/2017</td></tr><tr><td>Plumbing</td><td>10/29/2017</td><td>12/9/2017</td></tr><tr><td>Windows</td><td>11/22/2017</td><td>12/15/2017</td></tr><tr><td>HVAC</td><td>11/20/2017</td><td>12/20/2017</td></tr></table><hr><p>Dear Mr. Brawn:</p><p>I am going to tell you what I've told the last representative who contacted me. My house is simply not for sale. You could offer me 10 times your largest offer, and I still wouldn't take it. Be aware, I'm not being shrewd and holding out for more. I am just an old woman who has no use for any more money. This house and the memories I keep here mean more to me than anything your company can offer. I suggest you postpone your project while I'm still kicking around or build the mall around me for all I care. It doesn't matter. I'm not moving and that's that.</p><p>Elsie Macfield<br>October 2, 2017</p>`,
pz: `<p>親愛的 Macfield 女士：</p><p>我是 Arron Brawn，代表想購買您房產的開發商寫這封信。就像我們之前清楚告知您的，我們打算拆除所有收購的老房子，興建一座購物中心和一系列公寓大樓，讓您的社區——西雅圖 Mallard——重獲新生。您的房產估價為（這已是寬鬆的估計）15 萬美元，我們先前 75 萬美元的出價早該被接受了。您的房子是我們計畫的最後一個阻礙，從附上的時程表可以看出，您拒絕出售正成為一大障礙。我們本應在七天前開始興建 A 棟公寓。因此，我們準備為您的房產提出 100 萬美元這個再慷慨不過的價格。這筆錢不僅能讓您買到更好的房子，還能讓您安享晚年。</p><p>感謝您撥冗，<br>Arron Brawn</p><p><b>A 棟公寓工程時程表</b><br>開工日：2017/9/21<br>拆除準備：10/1–10/6<br>拆除：10/6–10/24<br>開挖：10/25–10/29<br>灌漿：11/1–11/13<br>回填：11/13–11/15<br>結構框架：10/25–12/5<br>屋頂：11/19–12/10<br>水電管線：10/29–12/9<br>窗戶：11/22–12/15<br>空調：11/20–12/20</p><hr><p>親愛的 Brawn 先生：</p><p>我要告訴你我跟上一位聯絡我的代表說過的話。我的房子就是不賣。就算你出你最高價的 10 倍，我也不會接受。請注意，我不是精明地在等更高的價錢。我只是一個不需要更多錢的老太太。這棟房子和我在這裡的回憶，對我來說比你們公司能提供的任何東西都重要。我建議你在我還活著的時候延後你們的計畫，或者乾脆繞著我蓋購物中心，我才不在乎。無所謂，我不會搬走，就這樣。</p><p>Elsie Macfield<br>2017 年 10 月 2 日</p>`,
qs: [
{n:91,q:"What are the developers trying to achieve?",qz:"開發商想要達成什麼？",o:["The drilling of oil","The revamping of a neighborhood","The purchasing of homes for the elderly","The renting out of the homes they purchased"],oz:["鑽探石油","改造社區","為老人購買住宅","出租他們買下的房子"],a:1,ex:"「to rejuvenate your neighborhood」→ 讓社區重獲新生 ＝ 改造社區（revamp）。"},
{n:92,q:"Which of the following is definitely true about Elsie Macfield?",qz:"關於 Elsie Macfield，下列何者一定正確？",o:["She is a wife and mother.","She is young and popular.","She is already very wealthy.","She is the last resident in Mallard."],oz:["她是妻子和母親。","她年輕又受歡迎。","她已經非常富有。","她是 Mallard 最後一位居民。"],a:3,ex:"「Your house is the last impediment to our project」→ 其他房子都已收購，她是最後一戶。她只說不需要更多錢，不代表很富有。"},
{n:93,q:"What is definitely known about Arron Brawn?",qz:"關於 Arron Brawn，可以確定的是什麼？",o:["He is the most senior developer.","He only has US$1,000,000 to spend.","He feels guilty about his business practices.","He is not the first representative to contact Elsie."],oz:["他是最資深的開發商。","他只有 100 萬美元可花。","他對自己的商業手法感到內疚。","他不是第一位聯絡 Elsie 的代表。"],a:3,ex:"Elsie 說「what I've told the last representative who contacted me」→ 之前有其他代表聯絡過她。"},
{n:94,q:"When did Arron Brawn send his letter?",qz:"Arron Brawn 什麼時候寄出這封信？",o:["October 2, 2017","September 21, 2017","September 27, 2018","September 28, 2017"],oz:["2017 年 10 月 2 日","2017 年 9 月 21 日","2018 年 9 月 27 日","2017 年 9 月 28 日"],a:3,ex:"開工日是 9/21，他說「本應在七天前開工」→ 9/21 + 7 ＝ 9/28。"},
{n:95,q:"At the time of Elsie Macfield's letter, which task should have been underway?",qz:"在 Elsie Macfield 寫信時，哪一項工程應該正在進行？",o:["Framing","Concrete","Demo prep","Demolition"],oz:["結構框架","灌漿","拆除準備","拆除"],a:2,ex:"Elsie 的信寫於 10/2，時程表上拆除準備是 10/1–10/6 → Demo prep。"}
]},
{ part: 7, title: "Part 7｜Mountain View Post 廣告費率",
passage: `<p>To: Paula Cramer<br>From: Barry Sanders<br>Subject: Advertising rates</p><p>Dear Ms. Cramer,</p><p>I am writing to inquire about the advertising rates in the <i>Mountain View Post</i> newspaper.</p><p>My company, Custom Printing Services Inc., or CPSI, offers inexpensive printing, binding, and other services for businesses and consumers. We have just expanded from our original location in San Francisco to Mountain View, and are now considering our promotion options in this market.</p><p>I would be very interested in getting information and rates for advertising in the <i>Mountain View Post</i>. I am especially interested in rates for half-page and full-page ads. I'd like to run ads for preferably a full year.</p><p>I would also appreciate any feedback you might have on promoting such a business in the Mountain View area. It is certainly a different market than San Francisco's. Perhaps we can talk by phone.</p><p>Thanks in advance. I look forward to hearing from you.</p><p>Sincerely,</p><p>Barry Sanders<br>CEO, Custom Printing Services Inc.<br><u>barry@CPSIPrinting.com</u></p><hr><p>To: Barry Sanders<br>From: Paula Cramer<br>Subject: RE: Advertising rates</p><p>Dear Barry,</p><p>Thank you for your inquiry. Below is a copy of our rate card. I will follow up with a telephone call, and we can discuss the local market in detail. I have some great advice on promotions here.</p><p>Thanks,</p><p>Paula Cramer<br>Advertising Director<br>Mountain View Post<br>(O) 555-230-9000, ext. 104</p><table><tr><th colspan="2">MOUNTAIN VIEW POST<br>Advertising Rate Card</th></tr><tr><th>No. of Weeks</th><th>Cost per Column Inch</th></tr><tr><td>6</td><td>$19.95</td></tr><tr><td>13</td><td>$17.70</td></tr><tr><td>26</td><td>$17.10</td></tr><tr><td>52</td><td>$15.95</td></tr><tr><td colspan="2">★ Based on a 6-column format, with each column measuring 1.75 inches in width. Special pricing available for half-page ads and special publications.</td></tr></table>`,
pz: `<p>收件者：Paula Cramer<br>寄件者：Barry Sanders<br>主旨：廣告費率</p><p>親愛的 Cramer 女士：</p><p>我寫信是想詢問《Mountain View 郵報》的廣告費率。</p><p>我的公司「客製印刷服務公司（CPSI）」為企業與消費者提供平價的印刷、裝訂及其他服務。我們剛從原本的舊金山據點擴展到 Mountain View，目前正在考慮在這個市場的宣傳方式。</p><p>我非常有興趣了解在《Mountain View 郵報》刊登廣告的資訊與費率，尤其是半版和全版廣告的費率。我希望最好能刊登一整年。</p><p>也很感謝您對在 Mountain View 地區推廣這類業務提供任何意見。這裡確實是和舊金山不同的市場。也許我們可以用電話聊聊。</p><p>先謝謝您，期待您的回覆。</p><p>CPSI 執行長 Barry Sanders 敬上</p><hr><p>收件者：Barry Sanders<br>寄件者：Paula Cramer<br>主旨：回覆：廣告費率</p><p>親愛的 Barry：</p><p>感謝您的詢問。以下是我們的費率表。我會再打電話給您，我們可以詳細討論當地市場。關於這裡的宣傳，我有一些很好的建議。</p><p>謝謝，<br>Paula Cramer<br>《Mountain View 郵報》廣告總監</p><p><b>《Mountain View 郵報》廣告費率表</b>（每欄吋價格）<br>6 週：$19.95<br>13 週：$17.70<br>26 週：$17.10<br>52 週：$15.95<br>★ 以 6 欄版面計算，每欄寬 1.75 吋。半版廣告及特刊另有特別價格。</p>`,
qs: [
{n:96,q:"Why does Barry want to learn about ad rates for the Mountain View Post?",qz:"Barry 為什麼想了解《Mountain View 郵報》的廣告費率？",o:["He is looking for discount rates.","He is trying to find out their competitor's rates.","His company offers inexpensive printing services.","His company is opening a branch in Mountain View."],oz:["他在找折扣價。","他想知道競爭對手的價格。","他的公司提供平價印刷服務。","他的公司要在 Mountain View 開分店。"],a:3,ex:"「We have just expanded… to Mountain View, and are now considering our promotion options in this market」→ 在當地開設據點，要打廣告。"},
{n:97,q:"In addition to advertising rates, what is Barry interested in?",qz:"除了廣告費率，Barry 還對什麼有興趣？",o:["Tips on how to market to Mountain View residents","How to design half-page and full-page ads","How the Mountain View and San Francisco markets are similar","Whether the Mountain View Post is interested in printing services"],oz:["如何向 Mountain View 居民行銷的建議","如何設計半版與全版廣告","兩地市場有何相似之處","郵報是否需要印刷服務"],a:0,ex:"「I would also appreciate any feedback you might have on promoting such a business in the Mountain View area」→ 當地行銷建議。他說兩地市場「不同」，(C) 錯。"},
{n:98,q:"How much would Barry have to pay for his preferred number of weeks?",qz:"以 Barry 偏好的刊登週數，他要付多少錢（每欄吋）？",o:["$19.95","$17.70","$17.10","$15.95"],oz:["$19.95","$17.70","$17.10","$15.95"],a:3,ex:"他想刊登一整年 ＝ 52 週 → $15.95。"},
{n:99,q:"What is something Barry asks for in his e-mail that Paula does NOT mention in her response?",qz:"Barry 在信中要求、但 Paula 回信中「沒有」提到的是什麼？",o:["Opinions on how to promote his business","How much a column inch costs for an ad running six weeks","Information on full-page ads","A telephone call"],oz:["如何推廣業務的意見","刊登六週的每欄吋價格","全版廣告的資訊","打電話"],a:2,ex:"Paula 的費率表只提到 half-page 有特別價格，沒有提到 full-page 廣告。推廣建議與電話她都有提到。"},
{n:100,q:"What will Paula talk about during her follow-up telephone call?",qz:"Paula 在後續電話中會談什麼？",o:["Advice on designing newspaper ads","How Barry can best promote his business in the Mountain View market","Whether Barry should expand his business to Mountain View","The cost of expanding to Mountain View"],oz:["設計報紙廣告的建議","Barry 如何在 Mountain View 市場推廣業務","Barry 是否該擴展到 Mountain View","擴展到 Mountain View 的成本"],a:1,ex:"「we can discuss the local market in detail. I have some great advice on promotions here」→ 當地市場的推廣建議。他已經擴展了，(C)(D) 錯。"}
]}
]
});
